import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    noise = rng.random()
    if noise < 0.03:
        return 'D' if noise < 0.015 else 'C'

    # If opponent has shown consistent cooperation, keep cooperating, but with
    # a light late-stage exploitation attempt against pure cooperators.
    if opp_d == 0:
        if n >= 12:
            # mostly cooperate, occasionally defect near the end
            if n >= 85 and rng.random() < 0.75:
                return 'D'
            if n >= 60 and rng.random() < 0.18:
                return 'D'
        return 'C'

    # If opponent is mostly defective, protect ourselves but probe for change.
    if opp_d >= opp_c + 3 or (n >= 6 and opp_c == 0):
        if n < 4:
            return 'D'
        if opp[-1] == 'C' and opp_c >= 2 and rng.random() < 0.55:
            return 'C'
        if opp[-1] == 'C' and n > 85 and rng.random() < 0.4:
            return 'C'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Main reciprocal/adaptive regime.
    last_me, last_opp = history[-1]

    # Forgiveness after mutual defection loops.
    recent = history[-6:]
    rec_me_d = sum(1 for x in recent if x[0] == 'D')
    rec_opp_d = sum(1 for x in recent if x[1] == 'D')
    if rec_opp_d >= 4 and rec_me_d >= 3:
        if rng.random() < 0.65:
            return 'C'

    # Reward recent cooperation strongly.
    if opp[-1] == 'C':
        if n > 90:
            # endgame: sometimes exploit a cooperator
            if rng.random() < 0.22:
                return 'D'
        return 'C'

    # Opponent last defected. Usually retaliate, but sometimes forgive.
    # Estimate recent forgiveness value.
    if n >= 8:
        cc = cd = dc = dd = 0
        for a, b in history[-8:]:
            if a == 'C' and b == 'C':
                cc += 1
            elif a == 'C' and b == 'D':
                cd += 1
            elif a == 'D' and b == 'C':
                dc += 1
            else:
                dd += 1
        # If we often defected into cooperation, that's profitable; continue.
        if dc >= 2 and cc >= 1:
            if rng.random() < 0.45:
                return 'D'
        # If mutual defection dominates, try to break out.
        if dd >= 3 and cc == 0:
            if rng.random() < 0.6:
                return 'C'

    # Tit-for-tat style with small probabilistic forgiveness.
    if opp[-1] == 'D':
        if rng.random() < 0.12:
            return 'C'
        return 'D'
    return 'C'
